-- Education history

create table "public"."educations" (
  "id" bigint primary key generated by default as identity,
  "icon" varchar,
  "institution" varchar,
  "degree" varchar,
  "period" varchar,
  "description" text,
  "user" uuid,
  "order" smallint,
  "is_active" boolean default true,
  "grade" real
);

alter table "public"."educations" add constraint "educations_user_fkey" foreign key ("user") references auth.users (id);

alter table "public"."educations" enable row level security;
create policy "Enable read access for all users" on "public"."educations" for select using (true);

grant all on "public"."educations" to postgres, anon, authenticated, service_role;
